  const visual=`<figure class="service-visual container"><img loading="lazy" decoding="async" src="/assets/images/${photo}" width="1440" height="810" alt="${esc(service?.[1]||'SpenceCom technology solution')} — installed or configured for a modern business workplace"/><figcaption>Illustrative technology concept. We assess the actual site, compatibility and security requirements before recommending equipment or platforms.</figcaption></figure>`;
