   const impact=`<section class="service-explainer"><span class="eyebrow">WHAT IT DOES · WHY IT MATTERS</span><h2>Understand the solution.<br><em>See the business value.</em></h2><div class="comparison-grid"><section><h3>What this technology does</h3><p>${esc(guide[0])}</p></section><section><h3>How it can improve productivity</h3><p>${esc(guide[1])}</p></section></div>${diagram}<h3>What SpenceCom implements</h3><ul>${guide[2].split('|').map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h3>How we make the transition smooth</h3><ol class="rollout-steps">${phases.map((x,i)=>`<li><strong>${String(i+1).padStart(2,'0')}</strong><span>${esc(x)}</span></li>`).join('')}</ol><p class="service-footnote">Every project starts with a review of your actual environment. We agree on a pilot, data protection, scheduling, user training and rollback arrangements where applicable before any critical cutover.</p><p><a href="/contact/" class="button button-teal">Arrange a free Google Meet, Teams or phone consultation ↗</a></p></section>`;
   html=html.replace('<h3>Where we work</h3>',`${impact}<h3>Where we work</h3>`);
