for(const [slug,name,desc,seo,summary] of services){const canon=`/solutions/${slug}/`;const linux=slug==='linux-desktops-call-centers';const body=breadcrumb([{name:'Solutions',href:'/solutions/'},{name}])+innerHero('SPENCECOM / SOLUTIONS',esc(name),desc)+`<section class="section"><div class="container content-grid"><article class="rich-content"><span class="eyebrow">THE SOLUTION</span><h2>${linux?'Cloud-ready workstations. Smarter operating costs.':'Make your technology an advantage.'}</h2><p class="lead">${esc(summary)}</p><p>${linux?'We can transform suitable PCs into productive Linux desktop workstations using Linux Mint Cinnamon, with a familiar desktop, managed browser applications and access to approved cloud services. Linux Mint is available without a Windows operating-system licence fee; deployment, administration, hardware and any commercial apps or subscriptions still have costs.':'Every engagement starts with a review of your goals and existing environment. We identify what can be retained, what needs to change and how to connect the technology into a dependable, secure and manageable solution.'}</p><h3>${linux?'Linux desktop and call centre services':'What we can help with'}</h3><ul>${linux?'<li>PC assessment, pilot imaging and Linux Mint Cinnamon configuration</li><li>Browser-based CRM, Microsoft 365 and Google Workspace access</li><li>Cloud workspace integration, device policies and endpoint management</li><li>Contact-centre browser softphone, WebRTC, headset and USB device compatibility validation</li><li>Secure remote access, updates, backups and staff onboarding</li><li>Cost comparison against Windows PCs, thin clients and virtual desktops</li>':'<li>Planning, technical assessment and solution architecture</li><li>Configuration, migration or on-site implementation as appropriate</li><li>Integration with existing business infrastructure</li><li>Security, validation, documentation and handover</li><li>Optional monitoring and ongoing improvement</li>'}</ul>${linux?'<h3>Is Linux suitable for every call centre?</h3><p>No. We validate the actual dialler, CRM, recording, security, identity, browser, peripherals and vendor support in a pilot first. Windows-only applications may require a different solution. Linux does not eliminate commercial software subscriptions, IT support or infrastructure costs.</p><h3>What is a cloud-ready workstation?</h3><p>It is a managed desktop or thin-client-style PC configured to access business applications and files through approved cloud or remote platforms. A full local Linux desktop is not the same as a thin client, but both can be cost-effective depending on the workflow.</p>':''}<h3>Where we work</h3><p>SpenceCom is based in Angeles City and Clark, Pampanga. We assess projects across the Philippines, including Luzon, Visayas and Mindanao. Suitable cloud, AI and consultancy work is available remotely to clients worldwide.</p><h3>How do we begin?</h3><p>Contact us for a free initial consultation. We'll discuss your current setup, requirements, timeline and practical next steps before proposing an implementation.</p></article><aside class="side-panel"><span class="eyebrow">START YOUR PROJECT</span><h3>Let's map the right next step.</h3><p>No pressure. Just a focused conversation about your requirements.</p><a class="button button-teal" href="/contact/">Free Consultation ↗</a><div class="mini-divider"></div><b>Related capabilities</b>${services.filter(x=>x[0]!==slug).slice(0,4).map(x=>`<a href="/solutions/${x[0]}/">${esc(x[1])} ↗</a>`).join('')}</aside></div></section>`+contactCta; write(`solutions/${slug}`,layout({title:seo,description:summary,canonical:canon,body,schema:[{'@context':'https://schema.org','@type':'Service',name,description:desc,provider:{'@type':'Organization',name:'SpenceCom',url:base},areaServed:{'@type':'Country',name:'Philippines'}}]}));}
