for(const [slug,name,desc] of places){write(`service-areas/${slug}`,layout({title:`Smart IT, Cloud & AI Solutions — ${name}`,description:desc,canonical:`/service-areas/${slug}/`,body:breadcrumb([{name:'Service Areas',href:'/service-areas/'},{name}])+innerHero('SERVICE AREAS',esc(name),desc)+`<section class="section"><div class="container content-grid"><article class="rich-content"><h2>Connected technology, wherever your business operates.</h2><p class="lead">${esc(desc)}</p><p>SpenceCom provides business networking, smart Wi-Fi, Microsoft 365, Google Workspace, email migration, NAS and hybrid storage, cloud server configuration, private AI and smart workplace consulting.</p><h3>On-site and remote delivery</h3><p>On-site implementation is subject to project scope, logistics and scheduling. Cloud, server, email migration, AI and consulting projects may be delivered remotely where appropriate.</p><h3>Plan with confidence</h3><p>We start with an initial consultation, assess existing infrastructure and present a practical scope. We do not claim a staffed physical branch in every service area.</p></article><aside class="side-panel"><h3>Discuss a project in ${esc(name)}</h3><p>Tell us about your location and requirements.</p><a class="button button-teal" href="/contact/">Get in touch ↗</a></aside></div></section>`+contactCta}));}
